    course_description = '<div class="content"> <p><b>(Note: This qualification does not contain any specialisation)</b></p> <p>This qualification reflects the role of individuals in a variety of Business Services job roles. These individuals may have frontline management accountabilities.</p> <p>Individuals in these roles carry out moderately complex tasks in a specialist field of expertise that requires business operations skills. They may possess substantial experience in a range of settings but seek to further develop their skills across a wide range of business functions.</p> </div>',
