UPDATE courses SET
    course_description = '<div class="content"> <p>General English (ELICOS) helps adult international students build practical English for everyday communication, community participation and life in Australia. Across five levels from Elementary to Advanced, students develop speaking, listening, reading and writing, supported by vocabulary, grammar and pronunciation practice.</p> <p>Students may enrol at the level appropriate to their current English proficiency. AIA uses placement information and assessment to support the starting-level decision and identify learning needs.</p> <p>General English may also support students who plan to continue to English for Academic Purposes (EAP) or further study. Entry into any VET or other course remains subject to the current entry requirements for that course, applicable government requirements and AIA’s assessment.</p> </div>',
    total_course_duration = '58 weeks',
    offshore_tuition_fee = '',
    entry_requirements = '',
    apply_form = 'https://auscanus.edu.au/courses/elicos-general-english/',
    updated_at = NOW()
WHERE cricos_course_code = '115159K';

UPDATE courses SET
    course_description = '<div class="content"> <p>English for Academic Purposes (EAP) is designed for adult international students who want to develop the English skills used in vocational and tertiary study. Across Intermediate, Upper-Intermediate and Advanced levels, students practise academic reading, writing, listening and speaking in contexts such as lectures, tutorials, presentations, research and assignments.</p> <p>The course supports students to build confidence with academic conventions, including note-taking, summarising, paraphrasing, essay and report writing, referencing and critical thinking.</p> <p>EAP may support preparation for further study. Entry into any VET, higher education or other course remains subject to the current entry requirements of the chosen course or provider, applicable government requirements and AIA’s assessment.</p> </div>',
    total_course_duration = '34 weeks',
    offshore_tuition_fee = '',
    entry_requirements = '',
    apply_form = 'https://auscanus.edu.au/courses/elicos-academic-purposes/',
    updated_at = NOW()
WHERE cricos_course_code = '115160F';

