UPDATE courses SET
    course_description = '<div class="content"> <p>This qualification reflects the role of individuals who apply highly specialised knowledge and skills in the field of organisational learning and capability development. Individuals in these roles generate and evaluate complex ideas. They also initiate, design and execute major learning and development functions within an organisation. Typically, they would have full responsibility and accountability for the personal output and work of others.</p> <p>This qualification may apply to leaders and managers in an organisation where learning is used to build organisational capability. The job roles that relate to this qualification may also include RTO Manager and RTO Director.</p> </div>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="content"> <p>This course is available to international students. There are no specific entry requirements listed in the qualification details or training package; however, applicants must meet Auscanus Institute of Australia’s entry requirements below:</p> <p><strong>Applicants must meet one of the following academic or work experience requirements:</strong></p> <p style="margin-bottom: 14px;">Successful completion of an Australian Diploma qualification or higher, or equivalent; or</p> <p style="margin-bottom: 14px;">Successful completion of Year 12 or equivalent secondary schooling with a minimum of two (2) years equivalent full-time relevant workplace experience in an operational or leadership role within an enterprise.</p> <p><strong>Applicants must also:</strong></p> <p style="margin-bottom: 14px;">Be 18 years of age or older at the time of course commencement.</p> <p style="margin-bottom: 14px;">Demonstrate English language proficiency through one of the following approved tests: IELTS Academic 6.0, TOEFL iBT 60, PTE Academic 50, or equivalent English language proficiency.</p> <p>English language competence may also be demonstrated through documented evidence of any of the following:</p> <p style="margin-bottom: 14px;">Completion of a recognised ELICOS program with an English proficiency level considered equivalent to the course entry requirements.</p> <p style="margin-bottom: 14px;">Completion of at least two (2) years of study in Australia at AQF Level 4 or higher.</p> <p style="margin-bottom: 14px;">Minimum five (5) years of study in English in Australia, the United Kingdom, the United States of America, Canada, New Zealand, South Africa or the Republic of Ireland.</p> <p style="margin-bottom: 14px;">Completion of Year 12 or equivalent secondary schooling in English.</p> <p><strong>Note:</strong> English language requirements and exemptions may vary depending on visa requirements and individual circumstances. Please contact AIA for further details or visit the <a href="https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500#HowTo" rel="noopener" target="_blank">Department of Home Affairs website</a>.</p> </div>',
    apply_form = 'https://auscanus.edu.au/courses/graduate-diploma-of-management-learning/',
    updated_at = NOW()
WHERE cricos_course_code = '117128A';

UPDATE courses SET
    course_description = '<div class="content"> <p>This qualification reflects the role of community services workers involved in the delivery, management and coordination of person-centred services to individuals, groups, and communities.</p> <p>At this level, workers have specialised skills in community services and work autonomously within their scope of practice under broad directions from senior management.</p> <p>Workers support people to make change in their lives to improve personal and social wellbeing and may also have responsibility for the supervision of other workers and volunteers. They may also undertake case management and program coordination.</p> <p>To achieve this qualification, the candidate must have completed at least 200 hours of work as detailed in the Assessment Requirements of units of competency. The skills in this qualification must be applied in accordance with Commonwealth and State or Territory legislation, Australian standards and industry codes of practice.</p> </div>',
    total_course_duration = '104 weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="content"> <p>This course is available to international students. There are no specific entry requirements listed in the qualification details or training package; however, applicants must meet Auscanus Institute of Australia’s entry requirements below:</p> <p><strong>Applicants must:</strong></p> <p style="margin-bottom: 14px;">Be 18 years of age or older at the time of course commencement.</p> <p style="margin-bottom: 14px;">Have successfully completed Year 12 or equivalent secondary schooling.</p> <p style="margin-bottom: 14px;">Demonstrate English language proficiency through one of the following approved tests: IELTS Academic 6.0, TOEFL iBT 60, PTE Academic 50, or equivalent English language proficiency.</p> <p>English language competence may also be demonstrated through documented evidence of any of the following:</p> <p style="margin-bottom: 14px;">Completion of a recognised ELICOS program with an English proficiency level considered equivalent to the course entry requirements.</p> <p style="margin-bottom: 14px;">Completion of at least two (2) years of study in Australia at AQF Level 4 or higher.</p> <p style="margin-bottom: 14px;">Minimum five (5) years of study in English in Australia, the United Kingdom, the United States of America, Canada, New Zealand, South Africa or the Republic of Ireland.</p> <p style="margin-bottom: 14px;">Completion of Year 12 or equivalent secondary schooling in English.</p> <p style="margin-bottom: 14px;">Applicants without documented evidence of English language proficiency may complete an online Language, Literacy, Numeracy and Digital Literacy (LLND) assessment and achieve a satisfactory outcome to meet AIA’s entry requirements.</p> <p><strong>Note:</strong> English language requirements and exemptions may vary depending on visa requirements and individual circumstances. Please contact AIA for further details or visit the <a href="https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500#HowTo" rel="noopener" target="_blank">Department of Home Affairs website</a>.</p> </div>',
    apply_form = 'https://auscanus.edu.au/courses/diploma-of-community-services/',
    updated_at = NOW()
WHERE cricos_course_code = '118319H';

UPDATE courses SET
    course_description = '<div class="content"> <p>This qualification reflects the role of individuals in the community, home or residential care setting who work under supervision and delegation as a part of a multi-disciplinary team, following an individualised plan to provide person-centred support to people who may require support due to ageing, disability or some other reason.</p> <p>These individuals take responsibility for their own outputs within the scope of their job role and delegation. Workers have a range of factual, technical and procedural knowledge, as well as some theoretical knowledge of the concepts and practices required to provide person-centred support.</p> <p>The skills in this qualification must be applied in accordance with Commonwealth and State/Territory legislation, Australian standards and industry codes of practice.</p> <p>To achieve this qualification, the candidate must have completed at least 120 hours of work as detailed in the Assessment Requirements of the units of competency.</p> </div>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = '',
